 21	
 22	interface OpenRouterModel {
 23	  id: string;
 24	  name: string;
 25	  context_length?: number;
 26	  pricing?: { prompt: string; completion: string; request?: string };
 27	}
 28	
 29	function formatPrice(perToken: string): string {
 30	  const v = parseFloat(perToken);
 31	  if (isNaN(v) || v === 0) return "free";
 32	  const perMillion = v * 1_000_000;
 33	  return perMillion < 0.01 ? `$${(perMillion).toFixed(3)}` : `$${perMillion.toFixed(2)}`;
 34	}
 35	
 36	function isFreeModel(pricing?: OpenRouterModel["pricing"]): boolean {
 37	  if (!pricing) return false;
 38	  return parseFloat(pricing.prompt) === 0 && parseFloat(pricing.completion) === 0;
 39	}
 40	
 41	interface SetupScreenProps {
 42	  onSetupSuccess: () => void;
 43	}
 44	
 45	interface ModelComboboxProps {
 46	  label: string;
 47	  placeholder: string;
 48	  value: string;
 49	  onChange: (v: string) => void;
 50	  models: OpenRouterModel[];
 51	  disabled?: boolean;
 52	}
 53	
 54	function ModelCombobox({ label, placeholder, value, onChange, models, disabled }: ModelComboboxProps) {
 55	  return (
 56	    <div className="space-y-1.5">
 57	      <label className="text-xs font-semibold text-muted-foreground">{label}</label>
 58	      {models.length > 0 ? (
 59	        <Combobox value={value} onValueChange={(v) => onChange(v ?? "")}>
 60	          <ComboboxInput
 61	            className="w-full"
 62	            placeholder={placeholder}
 63	            disabled={disabled}
 64	            showClear={!!value}
 65	          />
 66	          <ComboboxContent>
 67	            <ComboboxList>
 68	              <ComboboxEmpty>No models found</ComboboxEmpty>
 69	              {models.map((m) => (
 70	                <ComboboxItem key={m.id} value={m.id}>
 71	                  <span className="flex-1 truncate min-w-0">{m.name || m.id}</span>
 72	                  <span className="flex items-center gap-1.5 shrink-0 ml-2">
 73	                    {m.pricing ? (
 74	                      isFreeModel(m.pricing) ? (
 75	                        <span className="text-[10px] font-medium text-green-500 bg-green-500/10 px-1 rounded">Free</span>
 76	                      ) : (
 77	                        <span className="text-[10px] text-muted-foreground tabular-nums">
 78	                          {formatPrice(m.pricing.prompt)}↓ {formatPrice(m.pricing.completion)}↑
 79	                        </span>
 80	                      )
 81	                    ) : null}
 82	                    {m.context_length ? (
 83	                      <span className="text-[10px] text-muted-foreground/60">
 84	                        {m.context_length >= 1000 ? `${(m.context_length / 1000).toFixed(0)}k` : m.context_length}
 85	                      </span>
 86	                    ) : null}
 87	                  </span>
 88	                </ComboboxItem>
 89	              ))}
 90	            </ComboboxList>
 91	          </ComboboxContent>
 92	        </Combobox>
 93	      ) : (
 94	        <Input
 95	          type="text"
 96	          placeholder={placeholder}
 97	          value={value}
 98	          onChange={(e) => onChange(e.target.value)}
 99	          disabled={disabled}
100	        />
101	      )}
102	    </div>
103	  );
104	}
