106	export function SetupScreen({ onSetupSuccess }: SetupScreenProps) {
107	  const extensionConfig = useSettingsStore((s) => s.extensionConfig);
108	
109	  const [provider, setProvider] = useState(extensionConfig.apiProviderType || "openai_legacy");
110	  const [baseUrl, setBaseUrl] = useState(extensionConfig.apiBaseUrl || "https://openrouter.ai/api/v1");
111	  const [apiKey, setApiKey] = useState(extensionConfig.apiKey || "");
112	  const [thinkModel, setThinkModel] = useState(extensionConfig.defaultThinkModel || "");
113	  const [doModel, setDoModel] = useState(extensionConfig.defaultDoModel || "");
114	  const [models, setModels] = useState<OpenRouterModel[]>([]);
115	  const [fetchError, setFetchError] = useState<string | null>(null);
116	  const [isFetching, setIsFetching] = useState(false);
117	  const [fetchedOnce, setFetchedOnce] = useState(false);
118	  const [error, setError] = useState<string | null>(null);
119	  const [isLoading, setIsLoading] = useState(false);
120	
121	  const handleFetchModels = useCallback(async () => {
122	    if (!baseUrl || !apiKey) {
123	      setFetchError("Enter a Base URL and API Key first.");
124	      return;
125	    }
126	    setIsFetching(true);
127	    setFetchError(null);
128	    try {
129	      const list = await bridge.fetchProviderModels(baseUrl.trim(), apiKey.trim());
130	      setModels(list);
131	      setFetchedOnce(true);
132	      if (list.length === 0) setFetchError("No models returned by the API.");
133	    } catch (err) {
134	      setFetchError(err instanceof Error ? err.message : String(err));
135	    } finally {
136	      setIsFetching(false);
137	    }
138	  }, [baseUrl, apiKey]);
139	
140	  const handleSubmit = async (e: React.FormEvent) => {
141	    e.preventDefault();
142	    setIsLoading(true);
143	    setError(null);
144	
145	    try {
146	      const response = await bridge.updateExtensionSettings({
147	        "api.providerType": provider,
148	        "api.baseUrl": baseUrl.trim(),
149	        "api.key": apiKey.trim(),
150	        "api.defaultThinkModel": thinkModel.trim(),
151	        "api.defaultDoModel": doModel.trim(),
152	      });
153	
154	      if (response.ok) {
155	        onSetupSuccess();
156	      } else {
157	        setError("Failed to save settings");
158	      }
159	    } catch (err) {
160	      setError(err instanceof Error ? err.message : String(err));
161	    } finally {
162	      setIsLoading(false);
163	    }
164	  };
165	
166	  return (
167	    <div className="h-full flex items-center justify-center p-6 overflow-y-auto">
168	      <div className="max-w-md w-full space-y-6 my-auto">
169	        <div className="text-center space-y-2">
170	          <ConsiliumLogo className="h-32 mx-auto" />
171	          <h1 className="text-xl font-bold tracking-tight">API Setup</h1>
172	          <p className="text-xs text-muted-foreground">
173	            Configure your model provider and API key to connect to Consilium.
174	          </p>
175	        </div>
176	
177	        {error && (
178	          <div className="bg-destructive/10 border border-destructive/20 text-destructive text-xs rounded-lg p-3">
179	            {error}
180	          </div>
181	        )}
182	
183	        <form onSubmit={handleSubmit} className="space-y-4">
184	          <div className="space-y-1.5">
185	            <label className="text-xs font-semibold text-muted-foreground">Provider</label>
186	            <select
187	              value={provider}
188	              onChange={(e) => setProvider(e.target.value)}
189	              className="w-full h-9 rounded-md border border-input bg-background px-3 py-1 text-sm shadow-sm transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
190	            >
191	              <option value="openai_legacy">OpenRouter / OpenAI-compatible</option>
192	              <option value="openai_responses">OpenAI (Responses API)</option>
193	              <option value="kimi">Kimi</option>
194	              <option value="anthropic">Anthropic</option>
195	              <option value="google_genai">Google Gemini</option>
196	            </select>
197	          </div>
198	
199	          <div className="space-y-1.5">
200	            <label className="text-xs font-semibold text-muted-foreground">Base URL</label>
201	            <Input
202	              type="text"
203	              placeholder="https://openrouter.ai/api/v1"
204	              value={baseUrl}
205	              onChange={(e) => setBaseUrl(e.target.value)}
206	            />
207	          </div>
208	
209	          <div className="space-y-1.5">
210	            <label className="text-xs font-semibold text-muted-foreground">API Key</label>
211	            <Input
212	              type="password"
213	              placeholder="sk-..."
214	              value={apiKey}
215	              onChange={(e) => setApiKey(e.target.value)}
216	              required
217	            />
218	          </div>
219	
220	          {/* Fetch Models button */}
221	          <div className="flex items-center gap-2">
222	            <Button
223	              type="button"
224	              variant="outline"
225	              size="sm"
226	              className="w-full"
227	              onClick={handleFetchModels}
228	              disabled={isFetching || !apiKey || !baseUrl}
229	            >
230	              {isFetching ? (
231	                <span className="flex items-center gap-2">
232	                  <IconLoader2 className="size-3.5 animate-spin" />
233	                  Fetching models...
234	                </span>
235	              ) : (
236	                <span className="flex items-center gap-2">
237	                  {fetchedOnce ? (
238	                    <IconRefresh className="size-3.5" />
239	                  ) : (
240	                    <IconChevronDown className="size-3.5" />
241	                  )}
242	                  {fetchedOnce ? `Refresh models (${models.length})` : "Fetch available models"}
243	                </span>
244	              )}
245	            </Button>
246	            {fetchedOnce && !isFetching && (
247	              <span className="text-green-500 shrink-0">
248	                <IconCheck className="size-4" />
249	              </span>
250	            )}
251	          </div>
252	
253	          {fetchError && (
254	            <div className="bg-amber-500/10 border border-amber-500/20 text-amber-600 dark:text-amber-400 text-xs rounded-lg p-2.5">
255	              {fetchError}
256	            </div>
257	          )}
258	
259	          <ModelCombobox
260	            label="Think Model"
261	            placeholder={models.length > 0 ? "Search or select a model..." : "e.g. anthropic/claude-3.5-sonnet"}
262	            value={thinkModel}
263	            onChange={setThinkModel}
264	            models={models}
265	          />
266	
267	          <ModelCombobox
268	            label="Do Model"
269	            placeholder={models.length > 0 ? "Search or select a model..." : "e.g. qwen/qwen-2.5-coder-32b"}
270	            value={doModel}
271	            onChange={setDoModel}
272	            models={models}
273	          />
274	
275	          <Button type="submit" className="w-full h-9 justify-center" disabled={isLoading}>
276	            {isLoading ? (
277	              <span className="flex items-center gap-2">
278	                <IconLoader2 className="size-4 animate-spin" />
279	                Connecting...
280	              </span>
281	            ) : (
282	              "Connect"
283	            )}
284	          </Button>
285	        </form>
286	      </div>
287	    </div>
288	  );
289	}
